package com.arena.login.controller;
import com.arena.login.service.TokenService;import org.junit.jupiter.api.Test;import org.springframework.web.client.*;import org.springframework.http.*;import org.springframework.mock.web.*;import org.springframework.test.util.ReflectionTestUtils;import java.net.URI;import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;
class FacilityProxyTest {
 @Test void patchAndConflictDetailsSurviveGatewayWithoutLeakingUnknownFields()throws Exception{var core=mock(RestTemplate.class);var controller=new TokenController(mock(TokenService.class),core);ReflectionTestUtils.setField(controller,"coreUrl","http://example.invalid");var request=new MockHttpServletRequest("PATCH","/api/v1/academies/10/facilities/bulk");request.setContent("{\"facilities\":[]}".getBytes());request.setContentType("application/json");var session=new MockHttpSession();session.setAttribute("ACCESS_TOKEN","unit");session.setAttribute("LAST_PRESENCE_TOUCH",System.currentTimeMillis());when(core.exchange(any(URI.class),eq(HttpMethod.PATCH),any(HttpEntity.class),eq(byte[].class))).thenThrow(HttpClientErrorException.create(HttpStatus.CONFLICT,"conflict",HttpHeaders.EMPTY,"{\"errorCode\":\"FACILITY_VERSION_CONFLICT\",\"reasonCode\":\"STALE_VERSION\",\"description\":\"unsafe upstream detail\",\"conflicts\":[{\"facilityId\":1,\"code\":\"E1\",\"submittedVersion\":0,\"currentVersion\":1,\"secret\":\"do-not-forward\"}]}".getBytes(),java.nio.charset.StandardCharsets.UTF_8));var response=controller.proxyRequest(request,session);String body=new String(response.getBody(),java.nio.charset.StandardCharsets.UTF_8);assertEquals(409,response.getStatusCode().value());assertTrue(body.contains("STALE_VERSION"));assertTrue(body.contains("currentVersion"));assertFalse(body.contains("unsafe upstream"));assertFalse(body.contains("do-not-forward"));}
 @Test void generationKeepsIdempotencyHeaderAndCreatedResponse()throws Exception{var core=mock(RestTemplate.class);var controller=new TokenController(mock(TokenService.class),core);ReflectionTestUtils.setField(controller,"coreUrl","http://example.invalid");var request=new MockHttpServletRequest("POST","/api/v1/academies/10/sports/20/facilities/bulk");String key=java.util.UUID.randomUUID().toString();request.addHeader("Idempotency-Key",key);request.setContentType("application/json");byte[] payload="{\"facilities\":[{\"facilityType\":\"ENGLISH\",\"count\":1}]}".getBytes();request.setContent(payload);var session=new MockHttpSession();session.setAttribute("ACCESS_TOKEN","unit");session.setAttribute("LAST_PRESENCE_TOUCH",System.currentTimeMillis());when(core.exchange(any(URI.class),eq(HttpMethod.POST),any(HttpEntity.class),eq(byte[].class))).thenReturn(ResponseEntity.status(201).body("{\"facilities\":[{\"facilityId\":101}]}".getBytes()));var result=controller.proxyRequest(request,session);assertEquals(201,result.getStatusCode().value());var entity=org.mockito.ArgumentCaptor.forClass(HttpEntity.class);verify(core).exchange(any(URI.class),eq(HttpMethod.POST),entity.capture(),eq(byte[].class));assertEquals(key,entity.getValue().getHeaders().getFirst("Idempotency-Key"));assertArrayEquals(payload,(byte[])entity.getValue().getBody());}

 @Test void sportRuleErrorsSurviveGatewayWithSafeDescriptions()throws Exception{
  for(String code:java.util.List.of("SINGLE_SPORT_LIMIT_EXCEEDED","SPORT_SESSION_ACTIVE","SPORT_RESERVATION_EXISTS")){
   var core=mock(RestTemplate.class);var controller=new TokenController(mock(TokenService.class),core);ReflectionTestUtils.setField(controller,"coreUrl","http://example.invalid");var request=new MockHttpServletRequest("PUT","/api/academy/sports/11");request.setContentType("application/json");request.setContent("{\"version\":0,\"active\":true}".getBytes());var session=new MockHttpSession();session.setAttribute("ACCESS_TOKEN","unit");session.setAttribute("LAST_PRESENCE_TOUCH",System.currentTimeMillis());
   when(core.exchange(any(URI.class),eq(HttpMethod.PUT),any(HttpEntity.class),eq(byte[].class))).thenThrow(HttpClientErrorException.create(HttpStatus.CONFLICT,"conflict",HttpHeaders.EMPTY,("{\"errorCode\":\""+code+"\",\"description\":\"unsafe database detail\"}").getBytes(),java.nio.charset.StandardCharsets.UTF_8));
   var response=controller.proxyRequest(request,session);String body=new String(response.getBody(),java.nio.charset.StandardCharsets.UTF_8);assertEquals(409,response.getStatusCode().value());assertTrue(body.contains(code));assertTrue(body.contains(com.arena.login.exception.ErrorCode.valueOf(code).getDescription()));assertFalse(body.contains("unsafe database"));
  }
 }
}
